#include "ReportGenerator.hpp"
#include <fstream>
#include <sstream>
#include <iomanip>
#include <algorithm>
#include <stdexcept>
namespace multilog { namespace {
std::string esc(const std::string&s){std::string o;for(char c:s){switch(c){case '"':o+="\\\"";break;case '\\':o+="\\\\";break;case '\n':o+="\\n";break;case '\r':o+="\\r";break;case '\t':o+="\\t";break;default:o+=c;}}return o;}
std::string csvEsc(const std::string&s){std::string o="\"";for(char c:s){if(c=='\"')o+="\"\"";else o+=c;}return o+'\"';}
std::vector<std::pair<std::string,std::size_t>> top(const std::unordered_map<std::string,std::size_t>&m){std::vector<std::pair<std::string,std::size_t>>v(m.begin(),m.end());std::sort(v.begin(),v.end(),[](auto&a,auto&b){return a.second>b.second;});if(v.size()>10)v.resize(10);return v;}
std::string timeText(const std::optional<std::chrono::system_clock::time_point>&t){if(!t)return "unavailable";auto n=std::chrono::system_clock::to_time_t(*t);std::tm tm{};
#ifdef _WIN32
localtime_s(&tm,&n);
#else
gmtime_r(&n,&tm);
#endif
std::ostringstream o;o<<std::put_time(&tm,"%Y-%m-%d %H:%M:%S UTC");return o.str();}
}
std::string ReportGenerator::terminal(const AnalysisResult&r,const std::vector<Alert>&a){std::ostringstream o;o<<"MultiLog Analyzer\nEntries: "<<r.total<<" | valid: "<<r.valid<<" | invalid: "<<r.invalid<<" | matched: "<<r.filtered<<"\nSeverity:";if(r.severities.empty())o<<" unavailable";for(auto&p:r.severities)o<<" "<<p.first<<"="<<p.second;o<<"\nHTTP classes:";if(r.statusClasses.empty())o<<" unavailable";for(auto&p:r.statusClasses)o<<" "<<p.first<<"xx="<<p.second;o<<"\nTime range: "<<timeText(r.earliest)<<" to "<<timeText(r.latest)<<"\nDuration: "<<r.seconds<<" s; throughput: "<<(r.seconds>0?r.total/r.seconds:0)<<" lines/s; threads: "<<r.threadCount<<"\nRequests per minute buckets: "<<r.requestsPerMinute.size()<<"; common errors: "<<r.errors.size()<<"\nAlerts: "<<a.size()<<"\n";for(auto&x:a)o<<"  ["<<x.severity<<"] "<<x.type<<" IP="<<x.sourceIp<<" count="<<x.count<<" - "<<x.reason<<"\n";auto ips=top(r.ips);o<<"Top IPs:\n";for(auto&p:ips)o<<"  "<<p.first<<" "<<p.second<<"\n";auto urls=top(r.urls);o<<"Top URLs:\n";for(auto&p:urls)o<<"  "<<p.first<<" "<<p.second<<"\n";return o.str();}
std::string ReportGenerator::json(const AnalysisResult&r,const std::vector<Alert>&a){std::ostringstream o;o<<"{\n  \"total\": "<<r.total<<", \"valid\": "<<r.valid<<", \"invalid\": "<<r.invalid<<", \"matched\": "<<r.filtered<<",\n  \"duration_seconds\": "<<r.seconds<<", \"throughput_lines_per_second\": "<<(r.seconds>0?r.total/r.seconds:0)<<", \"threads\": "<<r.threadCount<<",\n  \"earliest\": \""<<timeText(r.earliest)<<"\", \"latest\": \""<<timeText(r.latest)<<"\",\n  \"severities\": {";bool first=true;for(auto&p:r.severities){if(!first)o<<',';first=false;o<<"\""<<esc(p.first)<<"\":"<<p.second;}o<<"},\n  \"status_classes\":{";first=true;for(auto&p:r.statusClasses){if(!first)o<<',';first=false;o<<"\""<<p.first<<"xx\":"<<p.second;}o<<"},\n  \"top_ips\":[";first=true;for(auto&p:top(r.ips)){if(!first)o<<',';first=false;o<<"{\"ip\":\""<<esc(p.first)<<"\",\"count\":"<<p.second<<"}";}o<<"],\n  \"top_urls\":[";first=true;for(auto&p:top(r.urls)){if(!first)o<<',';first=false;o<<"{\"url\":\""<<esc(p.first)<<"\",\"count\":"<<p.second<<"}";}o<<"],\n  \"common_errors\":[";first=true;for(auto&p:top(r.errors)){if(!first)o<<',';first=false;o<<"{\"message\":\""<<esc(p.first)<<"\",\"count\":"<<p.second<<"}";}o<<"],\n  \"requests_per_minute\":{";first=true;for(auto&p:r.requestsPerMinute){if(!first)o<<',';first=false;o<<"\""<<p.first<<"\":"<<p.second;}o<<"},\n  \"alerts\":[";first=true;for(auto&x:a){if(!first)o<<',';first=false;o<<"{\"type\":\""<<esc(x.type)<<"\",\"ip\":\""<<esc(x.sourceIp)<<"\",\"window\":\""<<esc(x.window)<<"\",\"count\":"<<x.count<<",\"severity\":\""<<esc(x.severity)<<"\",\"reason\":\""<<esc(x.reason)<<"\"}";}o<<"]\n}\n";return o.str();}
std::string ReportGenerator::csv(const AnalysisResult&r,const std::vector<Alert>&a){std::ostringstream o;o<<"record_type,key,value,source_ip,window,count,severity,reason\n";o<<"metric,total,"<<r.total<<",,,,,\nmetric,valid,"<<r.valid<<",,,,,\nmetric,invalid,"<<r.invalid<<",,,,,\nmetric,matched,"<<r.filtered<<",,,,,\nmetric,duration_seconds,"<<r.seconds<<",,,,,\nmetric,throughput_lines_per_second,"<<(r.seconds>0?r.total/r.seconds:0)<<",,,,,\n";for(auto&p:r.severities)o<<"severity,"<<csvEsc(p.first)<<','<<p.second<<",,,,,\n";for(auto&p:r.statusClasses)o<<"status_class,"<<p.first<<"xx,"<<p.second<<",,,,,\n";for(auto&p:r.ips)o<<"ip,"<<csvEsc(p.first)<<','<<p.second<<",,,,,\n";for(auto&p:r.urls)o<<"url,"<<csvEsc(p.first)<<','<<p.second<<",,,,,\n";for(auto&p:r.errors)o<<"error,"<<csvEsc(p.first)<<','<<p.second<<",,,,,\n";for(auto&p:r.requestsPerMinute)o<<"requests_per_minute,"<<p.first<<','<<p.second<<",,,,,\n";for(auto&x:a)o<<"alert,"<<csvEsc(x.type)<<",,"<<csvEsc(x.sourceIp)<<','<<csvEsc(x.window)<<','<<x.count<<','<<csvEsc(x.severity)<<','<<csvEsc(x.reason)<<"\n";return o.str();}
void ReportGenerator::write(const std::filesystem::path&p,const std::string&s){std::filesystem::create_directories(p.parent_path());std::ofstream f(p);if(!f)throw std::runtime_error("cannot create report: "+p.string());f<<s;if(!f)throw std::runtime_error("failed writing report: "+p.string());}
}
